export function InviteRow({
    index,
    isDeletable,
    hideProjectAccessSelector = false,
}: {
    index: number
    isDeletable: boolean
    hideProjectAccessSelector?: boolean
}): JSX.Element {
    const name = PLACEHOLDER_NAMES[index % PLACEHOLDER_NAMES.length]

    const { hasAvailableFeature, user } = useValues(userLogic)
    const hasAccessControl = hasAvailableFeature(AvailableFeature.ACCESS_CONTROL)

    const { invitesToSend, emailChecks, isInviting } = useValues(inviteLogic)
    const { updateInviteAtIndex, inviteTeamMembers, deleteInviteAtIndex, checkInviteEmail } = useActions(inviteLogic)
    const { preflight } = useValues(preflightLogic)
    const { currentOrganization } = useValues(organizationLogic)

    const myMembershipLevel = currentOrganization ? currentOrganization.membership_level : null

    const allowedLevels = myMembershipLevel
        ? organizationMembershipLevelIntegers.filter((listLevel) => listLevel <= myMembershipLevel)
        : [OrganizationMembershipLevel.Member]

    const allowedLevelsOptions = allowedLevels.map((level) => ({
        value: level,
        label: OrganizationMembershipLevel[level],
    }))
    const email = invitesToSend[index]?.target_email ?? ''
    const debouncedEmail = useDebouncedValue(email, 300)
    const isOwnEmail = !!email && email.trim().toLowerCase() === user?.email?.trim().toLowerCase()
    const emailCheck = emailChecks[email.trim().toLowerCase()]
    useEffect(() => {
        if (
            debouncedEmail &&
            isEmail(debouncedEmail) &&
            debouncedEmail.trim().toLowerCase() !== user?.email?.trim().toLowerCase()
        ) {
            checkInviteEmail(debouncedEmail)
        }
    }, [debouncedEmail, user?.email, checkInviteEmail])
    const emailError = isOwnEmail
        ? "You can't invite yourself."
        : emailCheck === 'member'
          ? 'This email already belongs to your organization.'
          : emailCheck === 'unknown'
            ? "Couldn't check this email. You can submit to validate it."
            : undefined

    return (
        <div className="space-y-4 bg-surface-secondary py-4 px-4 rounded-md">
            <div className="flex gap-2">
                <div className="flex-2">
                    <LemonInput
                        placeholder={`${name.toLowerCase()}@posthog.com`}
                        type="email"
                        className={`error-on-blur${!invitesToSend[index]?.isValid || emailError ? ' errored' : ''}`}
                        onChange={(v) => {
                            const isValid =
                                !v || (isEmail(v) && v.trim().toLowerCase() !== user?.email?.trim().toLowerCase())
                            updateInviteAtIndex({ target_email: v, isValid }, index)
                        }}
                        onBlur={() => {
                            if (email && isEmail(email) && !isOwnEmail) {
                                checkInviteEmail(email)
                            }
                        }}
                        value={invitesToSend[index]?.target_email}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                                if ((emailCheck === 'available' || emailCheck === 'unknown') && !isInviting) {
                                    inviteTeamMembers()
                                } else if (email && isEmail(email) && !isOwnEmail) {
                                    checkInviteEmail(email)
                                }
                            }
                        }}
                        autoFocus={index === 0}
                        data-attr="invite-email-input"
                    />
                    {emailError && (
                        <div className="mt-1 text-xs text-danger" role="alert">
                            {emailError}
                        </div>
                    )}
                </div>
                {preflight?.email_service_available && (
                    <div className="flex-1 flex gap-1 items-center justify-between">
                        <LemonInput
                            placeholder={name}
                            className="flex-1"
                            value={invitesToSend[index].first_name}
                            onChange={(v) => {
                                updateInviteAtIndex({ first_name: v }, index)
                            }}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !isInviting) {
                                    inviteTeamMembers()
                                }
                            }}
                        />
                    </div>
                )}
                {allowedLevelsOptions.length > 1 && (
                    <div className="flex-1 flex gap-1 items-center justify-between">
                        <LemonSelect
                            className="bg-bg-light"
                            fullWidth
                            data-attr="invite-row-org-member-level"
                            options={allowedLevelsOptions}
                            value={invitesToSend[index].level || allowedLevels[0]}
                            onChange={(v) => {
                                updateInviteAtIndex({ level: v }, index)
                            }}
                        />
                    </div>
                )}
                {!preflight?.email_service_available && (
                    <div className="flex-1 flex gap-1 items-center justify-between">
                        <LemonButton
                            type="primary"
                            className="flex-1"
                            disabled={
                                !invitesToSend[index].isValid ||
                                (emailCheck !== 'available' && emailCheck !== 'unknown') ||
                                isInviting
                            }
                            loading={isInviting}
                            onClick={() => {
                                inviteTeamMembers()
                            }}
                            fullWidth
                            center
                            data-attr="invite-generate-invite-link"
                        >
                            Submit
                        </LemonButton>
                    </div>
                )}

                {isDeletable && (
                    <LemonButton icon={<IconTrash />} status="danger" onClick={() => deleteInviteAtIndex(index)} />
                )}
            </div>

            {hasAccessControl && !hideProjectAccessSelector && <ProjectAccessSelector inviteIndex={index} />}
        </div>
    )
}

export function InviteTeamMatesComponent({
    hideProjectAccessSelector = false,
}: {
    hideProjectAccessSelector?: boolean
